<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Notification\Message\Domain\ValueObject\MessageUrgentVO;

trait MessageUrgentAccessor
{
    private MessageUrgentVO $_urgent;
    public function isUrgent(): bool
    {
        return $this->_urgent->value();
    }
    public function urgent(): MessageUrgentVO
    {
        return $this->_urgent;
    }
    public function isUrgentChanged(?self $original = null): bool
    {
        return !$this->_urgent->equals($original?->_urgent);
    }
    public function withUrgent(MessageUrgentVO|bool $urgent): self
    {
        $copy = clone $this;
        $copy->_urgent = MessageUrgentVO::from($urgent);
        return $copy;
    }
}
